// Paste into an n8n Code node: JavaScript / Run Once for All Items.
// Duplicate for each RSS branch and change SOURCE only.
// Values: aihot, hackernews, github, techmeme, huggingface
const SOURCE = 'hackernews';

const allowed = ['aihot', 'hackernews', 'github', 'techmeme', 'huggingface'];
if (!allowed.includes(SOURCE)) throw new Error('Unknown SOURCE: ' + SOURCE);

function decode(text) {
  const entities = {amp: '&', quot: '"', apos: "'", lt: '<', gt: '>', nbsp: ' '};
  return String(text ?? '').replace(/&(#x[0-9a-f]+|#\d+|amp|quot|apos|lt|gt|nbsp);/gi, (all, code) => {
    if (code[0] !== '#') return entities[code.toLowerCase()] ?? all;
    const n = /^#x/i.test(code) ? parseInt(code.slice(2), 16) : Number(code.slice(1));
    return n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : all;
  });
}

function plain(text) {
  return decode(String(text ?? '')
    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

// Strip only known tracking parameters from the identity key, not the fetch URL.
function canonical(url) {
  const clean = url.replace(/#.*$/, '');
  const pos = clean.indexOf('?');
  const base = (pos < 0 ? clean : clean.slice(0, pos))
    .replace(/^(https?:\/\/)([^/]+)/i, (_, scheme, host) => scheme.toLowerCase() + host.toLowerCase());
  if (pos < 0) return base;
  const query = clean.slice(pos + 1).split('&').filter(part =>
    !/^(utm_[^=]*|fbclid|gclid|msclkid|accessToken)=/i.test(part));
  return base + (query.length ? '?' + query.join('&') : '');
}

const seen = new Set();
const now = new Date();
const output = [];

for (const [index, item] of $input.all().entries()) {
  const j = item.json;
  const title = plain(j.title);
  if (!title || !j.link) continue; // A failed RSS node may produce an empty/error item.
  const html = String(j['content:encoded'] || j.content || j.description || '');
  const text = plain(html || j.contentSnippet);
  let url = decode(j.link).trim();

  if (SOURCE === 'aihot') {
    const original = html.match(/<a\b[^>]*href=["']([^"']+)["'][^>]*>\s*(?:阅读原文|原文链接|原文)\s*<\/a>/i);
    if (!original) throw new Error('AIHOT original link not found; inspect this RSS item: ' + title);
    url = decode(original[1]).trim();
  }
  if (SOURCE === 'techmeme') {
    const original = html.match(/<b\b[^>]*>\s*<a\b[^>]*href=["']([^"']+)["']/i);
    if (!original) throw new Error('Techmeme headline link not found; inspect this RSS item: ' + title);
    url = decode(original[1]).trim();
  }
  if (!/^https?:\/\//i.test(url)) continue;
  // Papers are fetched as abstract pages; this workflow does not download PDFs.
  if (SOURCE === 'huggingface') url = url.replace(/(arxiv\.org)\/pdf\//i, '$1/abs/').replace(/\.pdf(?=$|[?#])/i, '');

  const timestamp = Date.parse(j.isoDate || j.pubDate || '');
  const published = Number.isFinite(timestamp) ? new Date(timestamp).toISOString() : null;
  // Apply freshness only to news, not repository creation dates or paper submission dates.
  if (['aihot', 'hackernews', 'techmeme'].includes(SOURCE) && published && now.getTime() - timestamp > 72 * 3600 * 1000) continue;

  const canonicalUrl = canonical(url);
  const key = SOURCE + '|' + canonicalUrl;
  if (seen.has(key)) continue;
  seen.add(key);
  const upvotes = Number(text.match(/Upvotes:\s*([\d,]+)/i)?.[1]?.replace(/,/g, '') || 0);
  const sortScore = SOURCE === 'huggingface' ? upvotes
    : ['hackernews', 'github'].includes(SOURCE) ? 10000 - index
    : Number.isFinite(timestamp) ? timestamp : 0;

  output.push({
    json: {
      key,
      source: SOURCE,
      title,
      url,
      canonical_url: canonicalUrl,
      published_at: published,
      first_seen_at: now.toISOString(),
      sort_score: sortScore,
      rss_excerpt: text.slice(0, 4000),
      body: '',
      scrape_status: 'pending',
      scraped_at: null,
      scrape_error: '',
    },
    pairedItem: {item: index},
  });
}

return output;

