// Paste into an n8n Code node: JavaScript / Run Once for Each Item.
// Name the node immediately before HTTP Request exactly: 待抓取
const article = $('Remove Duplicates').item.json;
const response = $json;
const markdown = typeof response.data?.markdown === 'string' ? response.data.markdown : '';
const pageStatus = Number(response.data?.metadata?.statusCode || 200);
const ok = response.success === true && markdown.trim().length > 0 && pageStatus < 400;
const detail = response.error || response.message || (pageStatus >= 400 ? 'Page HTTP ' + pageStatus : 'Empty or invalid scrape response');

return {
  json: {
    ...article,
    body: ok ? markdown : '',
    scrape_status: ok ? 'ok' : 'failed',
    scraped_at: new Date().toISOString(),
    scrape_error: ok ? '' : (typeof detail === 'string' ? detail : JSON.stringify(detail)).slice(0, 1500),
  },
};
